import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>WebP 是很适合网页的格式，直到你需要编辑图片、打印它，或者在老软件里打开它。这时 PNG 就成了正确的目标。</p>\n<p>WebP 转 PNG 在实际意义上是无损的。像素原样保留，透明度得以保留，转换结果到处都能打开。</p>\n<p>这篇指南会讲清楚转换是怎么进行的，什么时候该用它，以及转出来的大文件该怎么看待。</p>\n<h2 id=\"what-is-webp-to-png\">什么是 WebP 转 PNG？</h2>\n<p>WebP 转 PNG 是读取一个 WebP 文件，再把它重写为 PNG。像素原样保留，转换本身不会丢失任何东西。</p>\n<p>如果原来的 WebP 是有损的，它已有的损伤也会一起保留下来。PNG 恢复不了 WebP 已经丢掉的细节，但也不会再增加新的损伤。</p>\n<p>透明度在转换中得以保留。透明的 WebP 标志转成 PNG 后还是透明的，透明通道和柔和边缘都一样。</p>\n<p>文件会变大，常常大得多。PNG 是无损格式，必须原样保存每个像素，而 WebP 可以丢掉细节来省体积。</p>\n<h2 id=\"is-it-truly-lossless\">WebP 转 PNG 真的无损吗？</h2>\n<p>转换这一步本身是无损的。WebP 里的每个像素都原样复制进 PNG，没有再简化，也没有再丢弃。</p>\n<p>但这不等于 PNG 就是完美的。如果 WebP 本来就是从 80% 画质的 JPG 转来的，PNG 会原样保留那 80% 的画质，瑕疵也一起保留。</p>\n<p>可以把它想成复印一张照片。复印件很精确，但不可能比原件更好，也恢复不了本来就不存在的细节。</p>\n<p>实际使用中，这个转换是安全的。PNG 和 WebP 一样好，而且之后再怎么保存 PNG，画质都不会再变差。</p>\n<h2 id=\"why-png-is-bigger\">为什么转出来的 PNG 更大？</h2>\n<p>WebP 比 PNG 更高效。有损 WebP 会丢掉细节来缩小文件，PNG 却必须原样保存每个像素，包括 WebP 压缩留下的痕迹。</p>\n<p>一张 200KB 的 WebP 照片可能变成 2MB 的 PNG。十倍的增长会让人吃惊，但对细节丰富的图片来说，这是正常且符合预期的。</p>\n<p>简单图形长得少一些。纯色区域多的标志转成的 PNG 不大，因为大面积纯色即使无损压缩效果也很好。</p>\n<p>多出来的体积，就是换取无损存储和通用兼容性的代价。你用字节换来了一个到处能打开、反复编辑也不会坏的文件。</p>\n<h2 id=\"transparency-survives\">透明度在转换中得以保留</h2>\n<p>透明的 WebP 标志转成 PNG 后还是透明的。透明通道原样复制，透明区域依然透明。</p>\n<p>柔和的阴影和半透明也得以保留。渐渐淡出的投影在 PNG 里依然平滑过渡。</p>\n<p>下载前用对比查看器检查一下结果。放大看标志边缘，确认透明度干净，没有光晕和毛边。</p>\n<p>要在很多种背景上使用的标志，PNG 是最安全的格式。它保留透明度，在每个编辑器、办公软件和浏览器里都能打开。</p>\n<h2 id=\"no-quality-slider\">为什么没有画质滑块？</h2>\n<p>WebP 转 PNG 的转换器上没有画质滑块，这才是对的。PNG 是无损格式，本来就没有什么画质档位可选。</p>\n<p>每个像素都原样保存，文件该多大就多大。没有任何设置能在不丢失数据的情况下让 PNG 变小，而 PNG 本来就不丢失数据。</p>\n<p>如果转出来的 PNG 太大了，问题在格式选错了，不在缺少设置。目的地允许的话，换成 JPG 就能得到更小的文件。</p>\n<p>这也提醒我们，PNG 是用来做特定工作的工具，不是通用的照片格式。该用无损的时候用它，其他地方就别用。</p>\n<h2 id=\"animated-webp\">动态 WebP 怎么办？</h2>\n<p>动态 WebP 和动图 GIF 一样，是会动的图片。转换器只会把第一帧画到画布上，所以结果是一张静态 PNG。</p>\n<p>这是正常现象，不是故障。PNG 本来就存不了动画，任何转成 PNG 的操作都只能得到静态图片。</p>\n<p>如果动画本身很重要，就别转 PNG。留着 WebP，或者用能保留动效的工具转成动态 GIF。</p>\n<p>如果只是想从动画里截一张静态图，第一帧通常就是最合适的。它是动画开始的那一帧，最能代表整个内容。</p>\n<h2 id=\"batch-converting\">批量转换 WebP 图片</h2>\n<p>一批 WebP 图片可以一次转成 PNG。每个文件独立转换，最后打包进一个 ZIP 里。</p>\n<p>单个文件最大支持 25MB，高清下载图和大尺寸截图都不用提前处理，直接就能转。</p>\n<p>留意总大小。一批 WebP 照片转成 PNG 后，ZIP 可能变得非常大，先确认目的地能不能处理这么大的文件。</p>\n<p>下载整批之前，先用对比查看器抽查一两个文件。确认透明度还在，颜色也对得上。</p>\n<h2 id=\"editing-workflow\">为编辑而转 WebP 成 PNG</h2>\n<p>编辑是把 WebP 转成 PNG 最好的理由。大多数桌面修图软件原生处理 PNG，WebP 的支持还在追赶。</p>\n<p>图片变成 PNG 后，可以反复编辑和保存，再也不会有进一步损失。每次 PNG 保存都是精确的，图片永远不会退化。</p>\n<p>在 PNG 版本上加文字、标注或叠加层。锐利的边缘经过多次编辑依然清晰，设计工作尤其需要这一点。</p>\n<p>完成后再按目的地的要求导出。网页要 WebP 或 JPG，打印店可能就要 PNG 本身。</p>\n<h2 id=\"where-png-works\">转出来的 PNG 能用在哪里？</h2>\n<p>转出来的 PNG 能在 Photoshop、Illustrator、Figma、Canva、PowerPoint 和所有现代浏览器里打开。它是图形和编辑的通用格式。</p>\n<p>它能上传到任何写明接受 PNG 的表单、网站和平台。政务系统、设计工具、打印店，全都接受 PNG。</p>\n<p>它打印出来也很干净。打印机只认 PNG 或 JPG，带锐利文字的 PNG 印出来和屏幕上看到的一模一样。</p>\n<p>它能直接粘贴进 Word 和 PowerPoint。文档里的 PNG 保持锐利的边缘和透明度，截图就该放在 PNG 里。</p>\n<h2 id=\"metadata\">元数据与颜色</h2>\n<p>WebP 转 PNG 会去掉 EXIF 元数据，包括相机信息和位置标签。画布只重画像素，元数据不会跟着过来。</p>\n<p>这对隐私是好事。分享出去的 PNG 不带拍摄地点和时间，比直接分享原文件更安全。</p>\n<p>色彩配置由浏览器编码器处理。大多数图片的颜色都保留得很准确，饱和度特别高的图片可能轻微偏移。</p>\n<p>产品照片这种对颜色敏感的工作，用之前把 PNG 和 WebP 仔细对比一下。偏移通常看不见，但值得检查。</p>\n<h2 id=\"screenshots-with-text\">带文字的截图</h2>\n<p>WebP 截图转成 PNG 后，文字保持绝对锐利。无损格式原样保存每个字母的边缘，没有任何变软。</p>\n<p>这让这个转换很适合必须经过编辑还保持可读的截图。给 PNG 加标注、裁剪、再保存，全部零损失。</p>\n<p>文件会比 WebP 大，有时大得多。截图必须保持完美的话，多出来的体积是合理的代价。</p>\n<p>截图直接放到网上时，那就留着 WebP。文件更小，加载更快，85% 画质下文字依然可读。</p>\n<h2 id=\"common-mistakes\">常见错误要避开</h2>\n<p>最常见的错误，是把 WebP 照片转成 PNG，指望画质变好。PNG 会原样保留 WebP，瑕疵也一起保留，文件却大得多。</p>\n<p>另一个错误是把整个文件夹的 WebP 照片都转成 PNG 放到网站上。PNG 照片比 WebP 大好几倍，页面会变得很慢。</p>\n<p>还有人忘了动态 WebP 转出来会变成静态图。动效很重要的话，根本就别转 PNG。</p>\n<p>最后，别把 WebP 转成 PNG 再转回 WebP，指望省空间。这样来回一趟没有任何好处，还可能带来新的压缩损伤。</p>\n<h2 id=\"webp-for-design-work\">设计工作中的 WebP 图片</h2>\n<p>设计工作常常从网上下载的图片开始，而这些图片通常是 WebP。转成 PNG 后，设计师就拿到了一份能经受编辑的无损工作副本。</p>\n<p>转换后在 Photoshop、Figma 或 Canva 里打开 PNG。无损格式能处理裁剪、文字叠加和颜色调整，每次保存都不会退化。</p>\n<p>设计完成要导出到网上时，再把成品转回 WebP。PNG 是工作格式，WebP 是上线网站的交付格式。</p>\n<p>把 WebP 原件和 PNG 一起留在项目文件夹里。设计要推倒重来时，原件还在，不用再下载一次。</p>\n<p>项目开始前先和团队商量好流程。大家对什么时候用 WebP、什么时候用 PNG 有共同理解，以后文件夹里就不会出现格式混杂的情况。</p>\n<h2 id=\"webp-for-print\">要打印的 WebP 图片</h2>\n<p>打印店只认 JPG 或 PNG，拿着 WebP 去可能直接被拒。发文件之前先转成 PNG，再确认一下打印店的具体要求。</p>\n<p>为打印而转换时要保留完整分辨率。800 像素宽的图片印 3 寸很清晰，印 10 寸就糊了，打印尺寸要和像素数匹配。</p>\n<p>转换后检查一下颜色，因为 WebP 和 PNG 处理色彩配置的方式略有不同。快速对比一下，就能确认打印颜色和屏幕颜色一致。</p>\n<p>带文字的打印文档，PNG 是正确的目标格式。无损格式让每个字母的边缘在纸上都锐利清晰，合同和表单尤其需要这一点。</p>\n<p>重要的活儿先印一张小样试试。一张小样就能确认颜色和清晰度，再决定要不要下大单。</p>\n<h2 id=\"webp-for-office-documents\">办公文档里的 WebP 图片</h2>\n<p>办公文档经常要用到网上的图片，而这些图片通常是 WebP。老版 Word 和 PowerPoint 可能显示不了，所以先转成 PNG。</p>\n<p>放进文档之前，先把 WebP 转成 PNG。PNG 在所有版本的 Office 里都能干净地嵌入，文档在任何同事的电脑上打开都正常。</p>\n<p>一份报告里有很多网络图片时，先把整批转好再开始写文档。这样就不会辛苦几小时后才发现一半图片都是坏的。</p>\n<p>转换后看一眼文件大小。二十张 2MB 的 PNG 放进报告就是 40MB，可能超出邮件附件上限，报告要发邮件的话记得先压缩图片。</p>\n<p>要打印的报告，带文字的图片就用 PNG。无损格式让字母在纸上保持锐利，有损格式却会把它们变软。</p>\n<h2 id=\"webp-for-archiving\">归档用的 WebP 图片</h2>\n<p>归档需要五十年后还能打开的格式，PNG 是更安全的选择。它快三十岁了，有史以来所有系统都支持，而 WebP 还很年轻。</p>\n<p>图片很重要时，把下载的 WebP 转成 PNG 再归档。PNG 原样保存像素，不管现在还是将来，任何软件都能打开。</p>\n<p>大存档的体积代价是实实在在的。WebP 照片转成 PNG 会大好几倍，所以要有选择地归档，而不是什么都转。</p>\n<p>存档按日期和来源分文件夹存放。2026-11-网站下载这样的文件夹名，几年后还很好找，叫“杂物”的文件夹就不行了。</p>\n<p>每隔几年检查一次存档。格式一直在变，母版用的格式过时了，可能要在旧格式读不出来之前先迁移。</p>\n<h2 id=\"webp-for-client\">为客户转换 WebP</h2>\n<p>客户常常从网站上收到 WebP 文件，却打不开。把文件转成 PNG，他们手里的每个软件都能打开这些图片了。</p>\n<p>转换前先问客户图片是用来做什么的。用来编辑的客户要 PNG，用来放网站的客户要 WebP。</p>\n<p>拿不准就两种格式都交付。PNG 文件到处能用，WebP 原件在网上又小，客户可以按用途自己选。</p>\n<p>转好的文件起个清楚的名字，带上用途和日期。logo-main.png 一看就知道是什么，download.webp 却什么都说明不了。</p>\n<p>交付时附一句简短的格式说明。一句话就能让客户不用再问，为什么每张图片都有两个副本。</p>\n<p>准备好转换了吗？打开 <a href=\"/zh/webp-zhuan-png/\">WebP 转 PNG 工具</a>，把文件拖进去就行。具体步骤可以看<a href=\"/zh/blog/ruhe-jiang-webp-zhuan-huan-wei-png/\">如何把 WebP 转换成 PNG</a>，编辑方面的问题可以看<a href=\"/zh/blog/webp-zhuan-png-bianji-jianrongxing/\">WebP 转 PNG：编辑、透明度与兼容性</a>。如果要的是更小的文件，<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>更合适。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"WebP 转 PNG 真的无损吗？","answer":"转换这一步本身是无损的：WebP 里的每个像素都原样复制进 PNG。但如果原来的 WebP 是有损的，它已有的损伤也会一起保留下来，因为 PNG 恢复不了已经丢掉的细节。PNG 和 WebP 一样好，但不会更好。"},{"question":"为什么转出来的 PNG 比 WebP 大这么多？","answer":"PNG 是无损格式，必须原样保存每个像素，包括 WebP 压缩留下的痕迹。一张 200KB 的 WebP 照片可能变成 2MB 的 PNG。简单图形长得少一些，因为纯色区域压缩起来很容易。多出来的体积就是换取无损存储和通用兼容性的代价。"},{"question":"透明的 WebP 标志转成 PNG 后还透明吗？","answer":"是的。透明通道原样复制，透明区域保持透明，柔和的阴影也依然渐渐淡出。下载前用对比查看器检查一下，放大看标志边缘，确认没有光晕或毛边。"},{"question":"动态 WebP 能转成 PNG 吗？","answer":"能转，但结果是静态图片。转换器只取第一帧，因为 PNG 存不了动画。如果需要保留动效，就留着 WebP，或者转成动态 GIF。第一帧通常是很有代表性的一张静态图。"},{"question":"WebP 转 PNG 有画质滑块吗？","answer":"没有，而且这才是对的。PNG 是无损格式，本来就没有什么画质档位可选。每个像素都原样保存，文件该多大就多大。PNG 太大了，说明格式选错了，不是有个设置没找到。"},{"question":"转换后的 PNG 文件能用在哪里？","answer":"所有能用 PNG 的地方：Photoshop、Illustrator、Figma、Canva、PowerPoint、Word、所有浏览器和所有打印店。转换后的 PNG 是标准文件，没有任何特殊要求，打开和打印都和别处创建的 PNG 一模一样。"}];
